<?php
/**
 * install_docs.php — YL v4 docs (VitePress, i18n: ru / en / zh-Hans / zh-Hant)
 * Весь файл — чистый ASCII. Юникод-символы YL вставляются через escape-последовательности.
 */
declare(strict_types=1);
$BASE = __DIR__;

/* ---------- Утилиты ---------- */
function y(string $s): string {
    static $m = null;
    if ($m === null) {
        $m = [
            '~DECL~'=>"\u{00A4}", '~FN~'=>"\u{00A7}", '~LAM~'=>"\u{03BB}",
            '~PR~'=>"\u{00BB}", '~O~'=>"\u{27E6}", '~C~'=>"\u{27E7}",
            '~EL~'=>"\u{00BF}", '~EACH~'=>"\u{21F6}", '~YLD~'=>"\u{21A4}",
            '~CLS~'=>"\u{2021}", '~MET~'=>"\u{22D4}", '~NEW~'=>"\u{21E2}",
            '~INH~'=>"\u{2020}", '~ASY~'=>"\u{26A1}", '~AWT~'=>"\u{23F8}",
            '~T~'=>"\u{2611}", '~F~'=>"\u{2610}", '~NUL~'=>"\u{2205}",
            '~TRY~'=>"\u{203C}", '~CTH~'=>"\u{2047}", '~FIN~'=>"\u{2326}",
            '~IMP~'=>"\u{2295}", '~DO~'=>"\u{27EA}", '~DC~'=>"\u{27EB}",
            '~BRK~'=>"\u{2298}", '~CNT~'=>"\u{21BB}", '~AST~'=>"\u{2261}",
            '~RAR~'=>"\u{2192}", '~UARR~'=>"\u{2191}",
        ];
    }
    return str_replace(array_keys($m), array_values($m), $s);
}
function w(string $rel, string $content): void {
    global $BASE;
    $p = $BASE . '/' . $rel;
    if (!is_dir(dirname($p))) mkdir(dirname($p), 0777, true);
    file_put_contents($p, y($content));
    echo "  + $rel (" . strlen($content) . " b)\n";
}

echo "YL v4 docs installer -> $BASE\n\n";

/* ---------- КОРНЕВЫЕ ФАЙЛЫ ---------- */
