ide/syntax' },\n          { text: 'Stdlib', link: '/zh-Hans/guide/stdlib' },\n        ]}],\n      },\n    },\n    'zh-Hant': {\n      label: 'Traditional Chinese (Taiwan)', lang: 'zh-Hant', link: '/zh-Hant/',\n      themeConfig: {\n        nav: [\n          { text: 'Guide der', link: '/zh-Hant/guide/getting-started' },\n          { text: 'Syntax', link: '/zh-Hant/guide/syntax' },\n          { text: 'Stdlib', link: '/zh-Hant/guide/stdlib' },\n        ],\n        sidebar: [{ text: 'Guide', items: [\n          { text: 'Getting started', link: '/zh-Hant/guide/getting-started' },\n          { text: 'Syntax', link: '/zh-Hant/guide/syntax' },\n          { text: 'Stdlib', link: '/zh-Hant/guide/stdlib' },\n        ]}],\n      },\n    },\n  },\n})\n");

